// A JS Map remembers insertion order, so it is already "hash map + linked list".
// delete + set moves a key to the end = most recently used; the first key is the victim.
class MapLru {
  constructor(capacity) {
    this.capacity = capacity;
    this.m = new Map();
  }

  get(key) {
    if (!this.m.has(key)) return undefined;
    const v = this.m.get(key);
    this.m.delete(key);
    this.m.set(key, v);                              // now the most recent
    return v;
  }

  put(key, value) {
    this.m.delete(key);
    this.m.set(key, value);
    if (this.m.size > this.capacity) this.m.delete(this.m.keys().next().value);   // evict the oldest
  }
}

const c = new MapLru(2);
c.put(1, 'A');
c.put(2, 'B');
c.get(1);                    // 1 becomes most recent
c.put(3, 'C');               // evicts 2
console.log([...c.m.keys()]);   // [ 1, 3 ]  (least recent first)
