class LRUCache {
  constructor(capacity) {
    this.cap = capacity;
    this.map = new Map();                       // key -> Node
    this.head = new Node(-1, -1);               // sentinels: head.next is the most recent
    this.tail = new Node(-1, -1);               // tail.prev is the least recent
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  get(key) {
    const n = this.map.get(key);
    if (n === undefined) return -1;
    this.unlink(n);
    this.pushFront(n);
    return n.val;
  }

  put(key, value) {
    let n = this.map.get(key);
    if (n !== undefined) {                      // an update counts as a use
      n.val = value;
      this.unlink(n);
      this.pushFront(n);
      return;
    }
    if (this.map.size === this.cap) {           // evict the least recently used
      const victim = this.tail.prev;
      this.unlink(victim);
      this.map.delete(victim.key);
    }
    n = new Node(key, value);
    this.pushFront(n);
    this.map.set(key, n);
  }

  unlink(n) { n.prev.next = n.next; n.next.prev = n.prev; }

  pushFront(n) {
    n.next = this.head.next; n.prev = this.head;
    this.head.next.prev = n; this.head.next = n;
  }
}
