    let h = 1;
    while (h < MAX && Math.random() < 0.5) h++;       // coin flips pick the height
    for (let i = this.level; i < h; i++) up[i] = this.head;
    this.level = Math.max(this.level, h);
    const n = new Node(num, h);
    for (let i = 0; i < h; i++) { n.next[i] = up[i].next[i]; up[i].next[i] = n; }
