// Out-of-order timestamps: keep each key's [time, value] pairs sorted; binary search finds the floor.
class TimeMapAnyOrder {
  constructor() { this.store = new Map(); }     // key -> sorted array of [time, value]

  set(key, value, ts) {
    if (!this.store.has(key)) this.store.set(key, []);
    const a = this.store.get(key);
    let lo = 0, hi = a.length;                  // first index with time >= ts
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (a[mid][0] < ts) lo = mid + 1; else hi = mid;
    }
    if (lo < a.length && a[lo][0] === ts) a[lo][1] = value;     // same timestamp: overwrite
    else a.splice(lo, 0, [ts, value]);                          // O(V) insert; a tree makes it O(log V)
  }

  get(key, ts) {
    const a = this.store.get(key);
    if (a === undefined) return '';
    let lo = 0, hi = a.length - 1, ans = -1;    // last index with time <= ts
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (a[mid][0] <= ts) { ans = mid; lo = mid + 1; } else hi = mid - 1;
    }
    return ans < 0 ? '' : a[ans][1];
  }
}
