// Wrap any iterable and cache one element ahead (LeetCode 284).
class PeekingIterator {
  constructor(iterable) {
    this.it = iterable[Symbol.iterator]();
    this.advance();                        // pre-fetch the first element
  }

  advance() { this.cur = this.it.next(); }   // { value, done }

  peek() {
    if (this.cur.done) throw new Error('no more elements');
    return this.cur.value;
  }

  hasNext() { return !this.cur.done; }       // idempotent: just reads the cache

  next() {
    if (this.cur.done) throw new Error('no more elements');
    const ans = this.cur.value;
    this.advance();                          // keep exactly one element cached
    return ans;
  }
}
