class Node {
  constructor() { this.kids = new Map(); this.top = []; }   // top: best 3 sentences through this node
}

class AutocompleteSystem {
  constructor(sentences, times) {
    this.root = new Node();
    this.cnt = new Map();
    this.typed = '';
    this.cur = this.root;
    sentences.forEach((s, i) => this.record(s, times[i]));
  }

  record(s, add) {
    this.cnt.set(s, (this.cnt.get(s) || 0) + add);
    const better = (a, b) => this.cnt.get(b) - this.cnt.get(a) || (a < b ? -1 : a > b ? 1 : 0);   // count desc, then ASCII
    let n = this.root;
    for (const ch of s) {
      if (!n.kids.has(ch)) n.kids.set(ch, new Node());
      n = n.kids.get(ch);
      if (!n.top.includes(s)) n.top.push(s);
      n.top.sort(better);
      if (n.top.length > 3) n.top.length = 3;
    }
  }

  input(c) {
    if (c === '#') {
      this.record(this.typed, 1);
      this.typed = '';
      this.cur = this.root;
      return [];
    }
    this.typed += c;
    if (this.cur !== null) this.cur = this.cur.kids.get(c) || null;   // null = fell off the trie
    return this.cur === null ? [] : [...this.cur.top];
  }
}
