// Strategy pattern: one cache, pluggable eviction policies. Great for "compare LRU vs FIFO" follow-ups.
// A policy has: onInsert(key), onAccess(key), victim() (choose and forget the key to evict), onRemove(key).
class LruPolicy {
  constructor() { this.order = new Set(); }               // first = least recent
  onInsert(k) { this.order.add(k); }
  onAccess(k) { this.order.delete(k); this.order.add(k); }   // move to the end = most recent
  victim() { const k = this.order.values().next().value; this.order.delete(k); return k; }
  onRemove(k) { this.order.delete(k); }
}

class FifoPolicy {
  constructor() { this.order = new Set(); }               // first = oldest insert
  onInsert(k) { this.order.add(k); }
  onAccess() { }                                          // FIFO ignores reads
  victim() { const k = this.order.values().next().value; this.order.delete(k); return k; }
  onRemove(k) { this.order.delete(k); }
}

class PolicyCache {
  constructor(capacity, policy) {
    this.capacity = capacity;
    this.policy = policy;
    this.data = new Map();
    this.hits = 0;
    this.misses = 0;
  }

  get(key) {
    if (!this.data.has(key)) { this.misses++; return undefined; }
    this.hits++;
    this.policy.onAccess(key);
    return this.data.get(key);
  }

  put(key, value) {
    if (this.data.has(key)) { this.data.set(key, value); this.policy.onAccess(key); return; }
    if (this.data.size === this.capacity) this.data.delete(this.policy.victim());
    this.data.set(key, value);
    this.policy.onInsert(key);
  }

  stats() { return 'hits=' + this.hits + ' misses=' + this.misses; }
}

const trace = [1, 2, 3, 1, 4, 1, 2, 5, 1, 2, 3, 4, 5];
for (const [name, policy] of [['LRU', new LruPolicy()], ['FIFO', new FifoPolicy()]]) {
  const c = new PolicyCache(3, policy);
  for (const k of trace) if (c.get(k) === undefined) c.put(k, k * 10);   // read-through on miss
  console.log(name + ': ' + c.stats());
}
