class Bucket {
  constructor(count) { this.count = count; this.keys = new Set(); this.prev = null; this.next = null; }
}

class AllOne {
  constructor() {
    this.head = new Bucket(0);        // sentinels; buckets run min -> max
    this.tail = new Bucket(0);
    this.head.next = this.tail;
    this.tail.prev = this.head;
    this.where = new Map();           // key -> its bucket
  }

  insertAfter(b, count) {
    const n = new Bucket(count);
    n.prev = b; n.next = b.next;
    b.next.prev = n; b.next = n;
    return n;
  }

  removeKey(b, key) {
    b.keys.delete(key);
    if (b.keys.size === 0) { b.prev.next = b.next; b.next.prev = b.prev; }   // unlink an empty bucket
  }

  inc(key) {
    const cur = this.where.get(key);
    const from = cur === undefined ? this.head : cur;
    const target = from.count + 1;
    let nxt = from.next;
    if (nxt === this.tail || nxt.count !== target) nxt = this.insertAfter(from, target);
    nxt.keys.add(key);
    this.where.set(key, nxt);
    if (cur !== undefined) this.removeKey(cur, key);
  }

  dec(key) {
    const cur = this.where.get(key);
    if (cur === undefined) return;
    if (cur.count === 1) {
      this.where.delete(key);
    } else {
      let prv = cur.prev;
      if (prv === this.head || prv.count !== cur.count - 1) prv = this.insertAfter(cur.prev, cur.count - 1);
      prv.keys.add(key);
      this.where.set(key, prv);
    }
    this.removeKey(cur, key);
  }

  getMaxKey() { return this.tail.prev === this.head ? '' : this.tail.prev.keys.values().next().value; }
  getMinKey() { return this.head.next === this.tail ? '' : this.head.next.keys.values().next().value; }
}
